using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "MoveOrbsCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/MoveOrbsCustomDescription", order = 0)]
public class MoveOrbsCustomDescription : CustomBattleActionDescription
{
	private const string moveOrbsActionBaseID = "MoveOrbsActionBase";

	private const string corruptedOrionMoveOrbsActionBaseID = "CorruptedOrionMoveOrbsActionBase";

	[SerializeField]
	private bool corruptedOrion;

	[SerializeField]
	[ShowIf("corruptedOrion")]
	private BattleAction corruptedOrionToGetDescription;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string localizedString = base.localizationManager.GetLocalizedString(corruptedOrion ? "CorruptedOrionMoveOrbsActionBase" : "MoveOrbsActionBase");
		BattleAction battleAction2 = (corruptedOrion ? corruptedOrionToGetDescription : battleAction);
		string localizedString2 = base.localizationManager.GetLocalizedString(battleAction2.BaseBattleActionData.ActionIDDescription);
		string firstArgument = Smart.Format(localizedString, localizedString2);
		return base.localizationManager.GetLocalizedXTimesFormatted(firstArgument, GetFinalAmountWithoutEquation(amountModified));
	}
}
